import{_ as n,C as t,o as s,c as i,E as a,a2 as p}from"./chunks/framework.uPk2SrVb.js";const h="/joinwell52/assets/approval-resume-20261029/approval-after-resume.figure.en.svg",f=JSON.parse('{"title":"Approved once. Can the AI resume in a new session?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Approved once. Can the AI resume in a new session?","date":"2026-10-29","published_date":"2026-10-29","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"How can the same Agent resume one approved operation in a new session without extending its scope?","summary":"An exact operation was approved, but a resumed Agent was asked to seek approval again. A two-layer CodeFlowMu comparison makes the ownership of an approval a testable question.","cover":"/assets/approval-resume-20261029/approval-after-resume.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Pinned private source; temporary-project approval-record and native tool comparisons; no remote operation","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-10-29-approval-after-resume.md","filePath":"en/research/2026-10-29-approval-after-resume.md","lastUpdated":null}'),c={name:"en/research/2026-10-29-approval-after-resume.md"};function l(d,e,u,g,m,v){const o=t("ArticleCover"),r=t("ArticleTableScroll");return s(),i("div",null,[a(o,{image:"/assets/approval-resume-20261029/approval-after-resume.cover-v1.png",kicker:"Engineering research · Recovery and authority",title:"Approved once. Can the AI resume in a new session?",summary:"An exact operation was approved, but a resumed Agent was asked to seek approval again. A two-layer CodeFlowMu comparison makes the ownership of an approval a testable question.",version:"2026-10-29",languageHref:"/zh/research/2026-10-29-approval-after-resume",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=p('<h1 id="approved-once-can-the-ai-resume-in-a-new-session" tabindex="-1">Approved once. Can the AI resume in a new session? <a class="header-anchor" href="#approved-once-can-the-ai-resume-in-a-new-session" aria-label="Permalink to &quot;Approved once. Can the AI resume in a new session?&quot;">​</a></h1><p>An AI assistant is about to push a specific branch. You inspect the target and approve that operation. Then its execution session ends unexpectedly. The assistant resumes in a new session and requests <strong>the very same operation</strong>.</p><p>Two outcomes would be troubling. The old approval might follow the new session without checking who or what changed. Or the system might forget the approved scope and ask you to press the same button repeatedly. A precise recovery rule needs both sides: <strong>a different actor, task, or target should be stopped; a legitimate retry by the same actor should retain its one approved opportunity.</strong></p><p>In current CodeFlowMu source, the second half proved harder than it sounds.</p><h2 id="why-three-upstream-changes-brought-us-back-to-our-own-approval-path" tabindex="-1">Why three upstream changes brought us back to our own approval path <a class="header-anchor" href="#why-three-upstream-changes-brought-us-back-to-our-own-approval-path" aria-label="Permalink to &quot;Why three upstream changes brought us back to our own approval path&quot;">​</a></h2><p>We did not try to reproduce another project&#39;s bug. <a href="https://github.com/openai/codex/pull/57978" target="_blank" rel="noreferrer">Codex&#39;s per-chat MCP leases</a> separate a shared connection from the identity of each chat using it. <a href="https://github.com/openai/openai-agents-js/pull/2085" target="_blank" rel="noreferrer">OpenAI Agents JS&#39;s client-owned environment preparation</a> preserves the owner of environment resolution across resume. <a href="https://github.com/paperclipai/paperclip/pull/17960" target="_blank" rel="noreferrer">Paperclip&#39;s durable write recovery</a> retains the original account, task, and request key; an account change cancels the old work. Together they raise a question: <strong>when execution continues, who is now acting, and which authorization still applies?</strong></p><p>CodeFlowMu has its own approved Agent retry path. We narrowed the question to a testable boundary: an approval names an Agent, a task, and one specific operation. After the session changes, how does the system decide whether the incoming request is still that operation?</p><h2 id="two-layers-answered-differently" tabindex="-1">Two layers answered differently <a class="header-anchor" href="#two-layers-answered-differently" aria-label="Permalink to &quot;Two layers answered differently&quot;">​</a></h2><p>We pinned a current private CodeFlowMu source revision and created controlled requests in a temporary directory. The example request was <code>git push origin main</code> by DEV-01 for TASK-1. We called only the approval decision path: <strong>no Git command ran and no remote service was contacted</strong>. After an ADMIN approval, we compared the approval-record API with the native tool gate that handles real tool requests.</p><table tabindex="0"><thead><tr><th>Retry condition</th><th>Approval-record API</th><th>Native tool gate</th></tr></thead><tbody><tr><td>Original session 1, exact approved operation</td><td>Available</td><td>Allowed once</td></tr><tr><td>New session 2, named as the decision&#39;s wake target</td><td>Cross-session continuation is intended by the API</td><td>Requires approval again</td></tr><tr><td>New session 3, same Agent, task, and operation</td><td>Can consume the approval once</td><td>Requires approval again</td></tr><tr><td>Different Agent, task, or command target</td><td>No match</td><td>Still requires approval</td></tr></tbody></table><p>After the original session consumed the approval, a second use was rejected. The existing approval module&#39;s tests also passed <strong>15/15</strong>, including a test stating that an approved Agent retry survives a resumed Session. The interesting discrepancy is therefore between <strong>the record API exercised by that test</strong> and <strong>the request built by the actual native tool gate</strong>.</p><p><img src="'+h+'" alt="The record API and native tool gate disagree about an exact operation in a new session"></p><p><em>Figure: decisions from the temporary-project probe. This diagram does not represent a Git push that actually occurred.</em></p><h2 id="how-the-approved-operation-lost-its-match" tabindex="-1">How the approved operation lost its match <a class="header-anchor" href="#how-the-approved-operation-lost-its-match" aria-label="Permalink to &quot;How the approved operation lost its match&quot;">​</a></h2><p>The record API computes an operation digest while excluding the session ID at the top level of the request. That leaves room for the same Agent to resume in a new session. It still checks Agent, task, project, operation fingerprint, and scope, and marks the authorization consumed after one use. That is a sensible intent.</p><p>The native tool gate, however, also places the session ID inside a <strong>nested snapshot of operation facts</strong>. When a new session rebuilds the request, the operation fingerprint remains the same, but the snapshot changes and so does the overall operation digest. Candidate matching requires both digest and fingerprint to match. The already approved record is therefore not found. Even session 2, which the decision named as its wake target, was asked for approval again; session 1 could consume it.</p><p>This is <strong>not evidence of an authorization bypass</strong>. Along the tested path, a legitimate continuation is blocked again. Simply deleting all session information would be careless: session identity matters for audit and accountability. The engineering question is which fields define the <strong>approved operation</strong>, and which describe <strong>the particular execution that carried it out</strong>.</p><h2 id="toward-an-approval-that-can-move-without-expanding" tabindex="-1">Toward an approval that can move without expanding <a class="header-anchor" href="#toward-an-approval-that-can-move-without-expanding" aria-label="Permalink to &quot;Toward an approval that can move without expanding&quot;">​</a></h2><p>Our experiment covers pinned source, temporary files, the approval record, and the native tool decision. <strong>We did not observe a customer incident or test real Host takeover, account switching, credential rotation, or remote outcomes.</strong> The current product source is private. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-10-29-resume-approval/00-report.en.md" target="_blank" rel="noreferrer">public evidence summary</a> gives the method, result table, and limits; it cannot let readers rerun the private Runtime.</p><p>Three questions remain:</p><ol><li><strong>Who owns the approval?</strong> Is a session the authorized subject, or a replaceable execution carrier? If the same Agent resumes twice, how is its current identity proved again?</li><li><strong>What exactly was approved?</strong> Target, content, task, and project must still match. If the Host, account, or credential owner changes, which gate requires a fresh decision?</li><li><strong>What happened before recovery?</strong> If a request reached a remote service and its receipt was lost, consuming an approval once does not prove the remote effect happened once. Recovery must verify the outcome before replaying.</li></ol><p>For users, both “approved” and “please approve again” deserve the same follow-up: <strong>is this a legitimate continuation of the exact operation, or has its scope changed?</strong> For engineers, the challenge is to let an approval survive recovery without turning it into a pass that works for a different actor or target. <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',22))])}const b=n(c,[["render",l]]);export{f as __pageData,b as default};
